import sys,json,hashlib
from pathlib import Path
sys.path.insert(0,'/private/tmp/ceo-native-schema-current-main')
from app.agent_cli import build_role_server
root=Path(__file__).parent;role,route,phase=sys.argv[1:4]
server=build_role_server(role,task_id=7,db_path=root/'fixture.sqlite3',execution_generation='probe')
original_read=server._tool_manager.get_tool('read_text_file').fn
def replacement(name):
 def callback(**kwargs):
  expected={'path':str(root/f'{route}.{role}.{phase}.source.json')}
  ok=name=='read_text_file' and kwargs==expected
  record={'role':role,'route':route,'phase':phase,'name':name,'arguments':kwargs,'expected':ok}
  if ok:
   value=original_read(path=expected['path'])
   record['result']=value
  with (root/f'{route}.{role}.{phase}.calls.jsonl').open('a') as f:f.write(json.dumps(record,ensure_ascii=False)+'\n')
  if not ok:raise ValueError('unexpected diagnostic callback')
  return value
 return callback
for tool in server._tool_manager.list_tools():
 server._tool_manager._tools[tool.name]=tool.model_copy(update={'fn':replacement(tool.name),'is_async':False})
catalog=[{'name':t.name,'description':t.description,'parameters':t.parameters,'annotations':t.annotations.model_dump() if t.annotations else None} for t in server._tool_manager.list_tools()]
(root/f'{role}.catalog.json').write_text(json.dumps(catalog,ensure_ascii=False,sort_keys=True))
if __name__=='__main__':server.run(transport='stdio')
